-- Designing a URL Shortener
insert into public.articles (owner_id, slug, title, summary, tags, has_brief, reading_minutes)
values ('00000000-0000-4000-a000-000000000002', 'url-shortener', 'Designing a URL Shortener', 'Requirements, API, storage and scaling for a TinyURL-style service.', '{system-design}', true, 3);
-- (separate statement: the draft row is created by the on_article_created trigger)
update public.article_drafts set doc = '{"type":"doc","content":[{"type":"heading","attrs":{"level":2,"sectionId":"s_0002","frameId":"frame_0001"},"content":[{"type":"text","text":"Requirements"}]},{"type":"paragraph","content":[{"type":"text","text":"Users submit a long URL and get a short alias; visiting the alias redirects to the original."}]},{"type":"bulletList","attrs":{"visibility":"brief"},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"100M new URLs a month"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Reads outnumber writes 100 : 1"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Redirect under 50 ms"}]}]}]},{"type":"paragraph","attrs":{"visibility":"detail"},"content":[{"type":"text","text":"Non-goals for v1: custom domains, analytics dashboards and editing a link after it is created."}]},{"type":"heading","attrs":{"level":2,"sectionId":"s_0009","frameId":"frame_0008"},"content":[{"type":"text","text":"High-level design"}]},{"type":"paragraph","content":[{"type":"text","text":"Clients call a stateless API service behind a load balancer. Short codes map to long URLs in a key-value store."}]},{"type":"callout","attrs":{"tone":"mint"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Key idea: generate IDs from a counter and encode them in base62 — 7 characters give 3.5 trillion codes."}]}]},{"type":"details","attrs":{"tone":"sky"},"content":[{"type":"detailsSummary","content":[{"type":"text","text":"Why not hash the long URL?"}]},{"type":"detailsContent","content":[{"type":"paragraph","content":[{"type":"text","text":"Hashes collide and need a retry loop; a counter never collides and keeps codes short."}]}]}]},{"type":"heading","attrs":{"level":2,"sectionId":"s_000j","frameId":"frame_000i"},"content":[{"type":"text","text":"Scaling reads"}]},{"type":"paragraph","content":[{"type":"text","text":"Most traffic is redirects, so cache hot codes at the edge and in Redis; misses go to read replicas."}]},{"type":"callout","attrs":{"tone":"red"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Watch out: cache 301 redirects carefully — browsers keep them forever."}]}]}]}'::jsonb, canvas = '{"layout":"50-50","files":{},"elements":[{"id":"frame_0001","type":"frame","x":0,"y":0,"width":1400,"height":1400,"name":"Requirements"},{"id":"r_0003","type":"rectangle","x":120,"y":220,"width":320,"height":130,"frameId":"frame_0001","strokeColor":"#0f766e","backgroundColor":"#ccfbf1","fillStyle":"solid","roundness":{"type":3},"strokeWidth":2,"roughness":1},{"id":"t_0004","type":"text","x":150,"y":268,"width":260,"height":35,"frameId":"frame_0001","text":"Shorten URL","originalText":"Shorten URL","fontSize":28,"fontFamily":5,"textAlign":"center","verticalAlign":"middle","strokeColor":"#1e1e1e","autoResize":false,"lineHeight":1.25},{"id":"r_0005","type":"rectangle","x":540,"y":220,"width":320,"height":130,"frameId":"frame_0001","strokeColor":"#b45309","backgroundColor":"#fef3c7","fillStyle":"solid","roundness":{"type":3},"strokeWidth":2,"roughness":1},{"id":"t_0006","type":"text","x":570,"y":268,"width":260,"height":35,"frameId":"frame_0001","text":"Redirect fast","originalText":"Redirect fast","fontSize":28,"fontFamily":5,"textAlign":"center","verticalAlign":"middle","strokeColor":"#1e1e1e","autoResize":false,"lineHeight":1.25},{"id":"a_0007","type":"arrow","x":440,"y":285,"width":100,"height":0,"frameId":"frame_0001","points":[[0,0],[100,0]],"strokeColor":"#1e1e1e","endArrowhead":"arrow","strokeWidth":2,"roughness":1},{"id":"frame_0008","type":"frame","x":7400,"y":0,"width":1400,"height":1400,"name":"High-level design"},{"id":"r_000a","type":"rectangle","x":7520,"y":220,"width":320,"height":130,"frameId":"frame_0008","strokeColor":"#0369a1","backgroundColor":"#e0f2fe","fillStyle":"solid","roundness":{"type":3},"strokeWidth":2,"roughness":1},{"id":"t_000b","type":"text","x":7550,"y":268,"width":260,"height":35,"frameId":"frame_0008","text":"Client","originalText":"Client","fontSize":28,"fontFamily":5,"textAlign":"center","verticalAlign":"middle","strokeColor":"#1e1e1e","autoResize":false,"lineHeight":1.25},{"id":"r_000c","type":"rectangle","x":7940,"y":220,"width":320,"height":130,"frameId":"frame_0008","strokeColor":"#0f766e","backgroundColor":"#ccfbf1","fillStyle":"solid","roundness":{"type":3},"strokeWidth":2,"roughness":1},{"id":"t_000d","type":"text","x":7970,"y":268,"width":260,"height":35,"frameId":"frame_0008","text":"API service","originalText":"API service","fontSize":28,"fontFamily":5,"textAlign":"center","verticalAlign":"middle","strokeColor":"#1e1e1e","autoResize":false,"lineHeight":1.25},{"id":"a_000e","type":"arrow","x":7840,"y":285,"width":100,"height":0,"frameId":"frame_0008","points":[[0,0],[100,0]],"strokeColor":"#1e1e1e","endArrowhead":"arrow","strokeWidth":2,"roughness":1},{"id":"r_000f","type":"rectangle","x":8360,"y":220,"width":320,"height":130,"frameId":"frame_0008","strokeColor":"#b45309","backgroundColor":"#fef3c7","fillStyle":"solid","roundness":{"type":3},"strokeWidth":2,"roughness":1},{"id":"t_000g","type":"text","x":8390,"y":268,"width":260,"height":35,"frameId":"frame_0008","text":"Key-value store","originalText":"Key-value store","fontSize":28,"fontFamily":5,"textAlign":"center","verticalAlign":"middle","strokeColor":"#1e1e1e","autoResize":false,"lineHeight":1.25},{"id":"a_000h","type":"arrow","x":8260,"y":285,"width":100,"height":0,"frameId":"frame_0008","points":[[0,0],[100,0]],"strokeColor":"#1e1e1e","endArrowhead":"arrow","strokeWidth":2,"roughness":1},{"id":"frame_000i","type":"frame","x":14800,"y":0,"width":1400,"height":1400,"name":"Scaling reads"},{"id":"r_000k","type":"rectangle","x":14920,"y":220,"width":320,"height":130,"frameId":"frame_000i","strokeColor":"#0f766e","backgroundColor":"#ccfbf1","fillStyle":"solid","roundness":{"type":3},"strokeWidth":2,"roughness":1},{"id":"t_000l","type":"text","x":14950,"y":268,"width":260,"height":35,"frameId":"frame_000i","text":"CDN / cache","originalText":"CDN / cache","fontSize":28,"fontFamily":5,"textAlign":"center","verticalAlign":"middle","strokeColor":"#1e1e1e","autoResize":false,"lineHeight":1.25},{"id":"r_000m","type":"rectangle","x":15340,"y":220,"width":320,"height":130,"frameId":"frame_000i","strokeColor":"#b45309","backgroundColor":"#fef3c7","fillStyle":"solid","roundness":{"type":3},"strokeWidth":2,"roughness":1},{"id":"t_000n","type":"text","x":15370,"y":268,"width":260,"height":35,"frameId":"frame_000i","text":"Read replicas","originalText":"Read replicas","fontSize":28,"fontFamily":5,"textAlign":"center","verticalAlign":"middle","strokeColor":"#1e1e1e","autoResize":false,"lineHeight":1.25},{"id":"a_000o","type":"arrow","x":15240,"y":285,"width":100,"height":0,"frameId":"frame_000i","points":[[0,0],[100,0]],"strokeColor":"#1e1e1e","endArrowhead":"arrow","strokeWidth":2,"roughness":1}]}'::jsonb
