-- (separate statement: the draft row is created by the on_article_created trigger)
update public.article_drafts set doc = '{"type":"doc","content":[{"type":"heading","attrs":{"level":2,"sectionId":"s_000q","frameId":"frame_000p"},"content":[{"type":"text","text":"The problem"}]},{"type":"paragraph","content":[{"type":"text","text":"With modulo hashing, changing N remaps almost every key — a cache stampede on every deploy."}]},{"type":"heading","attrs":{"level":2,"sectionId":"s_000u","frameId":"frame_000t"},"content":[{"type":"text","text":"The ring"}]},{"type":"paragraph","content":[{"type":"text","text":"Place servers and keys on a ring; each key belongs to the next server clockwise."}]},{"type":"details","attrs":{"tone":"mint"},"content":[{"type":"detailsSummary","content":[{"type":"text","text":"Virtual nodes"}]},{"type":"detailsContent","content":[{"type":"paragraph","content":[{"type":"text","text":"Each server takes many points on the ring so load evens out."}]}]}]}]}'::jsonb, canvas = '{"layout":"40-60","files":{},"elements":[{"id":"frame_000p","type":"frame","x":0,"y":0,"width":1600,"height":1200,"name":"The problem"},{"id":"r_000r","type":"rectangle","x":120,"y":220,"width":320,"height":130,"frameId":"frame_000p","strokeColor":"#0369a1","backgroundColor":"#e0f2fe","fillStyle":"solid","roundness":{"type":3},"strokeWidth":2,"roughness":1},{"id":"t_000s","type":"text","x":150,"y":268,"width":260,"height":35,"frameId":"frame_000p","text":"hash(key) % N","originalText":"hash(key) % N","fontSize":28,"fontFamily":5,"textAlign":"center","verticalAlign":"middle","strokeColor":"#1e1e1e","autoResize":false,"lineHeight":1.25},{"id":"frame_000t","type":"frame","x":7600,"y":0,"width":1600,"height":1200,"name":"The ring"},{"id":"r_000v","type":"rectangle","x":7720,"y":220,"width":320,"height":130,"frameId":"frame_000t","strokeColor":"#0f766e","backgroundColor":"#ccfbf1","fillStyle":"solid","roundness":{"type":3},"strokeWidth":2,"roughness":1},{"id":"t_000w","type":"text","x":7750,"y":268,"width":260,"height":35,"frameId":"frame_000t","text":"Node A","originalText":"Node A","fontSize":28,"fontFamily":5,"textAlign":"center","verticalAlign":"middle","strokeColor":"#1e1e1e","autoResize":false,"lineHeight":1.25},{"id":"r_000x","type":"rectangle","x":8140,"y":220,"width":320,"height":130,"frameId":"frame_000t","strokeColor":"#0f766e","backgroundColor":"#ccfbf1","fillStyle":"solid","roundness":{"type":3},"strokeWidth":2,"roughness":1},{"id":"t_000y","type":"text","x":8170,"y":268,"width":260,"height":35,"frameId":"frame_000t","text":"Node B","originalText":"Node B","fontSize":28,"fontFamily":5,"textAlign":"center","verticalAlign":"middle","strokeColor":"#1e1e1e","autoResize":false,"lineHeight":1.25},{"id":"a_000z","type":"arrow","x":8040,"y":285,"width":100,"height":0,"frameId":"frame_000t","points":[[0,0],[100,0]],"strokeColor":"#1e1e1e","endArrowhead":"arrow","strokeWidth":2,"roughness":1},{"id":"r_0010","type":"rectangle","x":8560,"y":220,"width":320,"height":130,"frameId":"frame_000t","strokeColor":"#0f766e","backgroundColor":"#ccfbf1","fillStyle":"solid","roundness":{"type":3},"strokeWidth":2,"roughness":1},{"id":"t_0011","type":"text","x":8590,"y":268,"width":260,"height":35,"frameId":"frame_000t","text":"Node C","originalText":"Node C","fontSize":28,"fontFamily":5,"textAlign":"center","verticalAlign":"middle","strokeColor":"#1e1e1e","autoResize":false,"lineHeight":1.25},{"id":"a_0012","type":"arrow","x":8460,"y":285,"width":100,"height":0,"frameId":"frame_000t","points":[[0,0],[100,0]],"strokeColor":"#1e1e1e","endArrowhead":"arrow","strokeWidth":2,"roughness":1}]}'::jsonb
